import csv
import io


def partition_enrollment(csv_text):
    if not isinstance(csv_text, str):
        raise TypeError("csv_text must be a string")
    result = {"starter": [], "experienced": [], "warnings": []}
    if not csv_text:
        return result

    try:
        reader = csv.DictReader(io.StringIO(csv_text), strict=True)
        if reader.fieldnames is None:
            return result
        required = {"given", "family", "contact", "tier"}
        if not required.issubset(reader.fieldnames):
            raise ValueError("required header columns are missing")
        for row in reader:
            row_number = reader.line_num
            if None in row or any(row.get(name) is None for name in required):
                result["warnings"].append(f"row {row_number}: malformed")
                continue
            values = {name: row[name].strip() for name in required}
            if any(not values[name] for name in required):
                result["warnings"].append(f"row {row_number}: malformed")
                continue
            applicant = (values["given"], values["family"], values["contact"])
            tier = values["tier"].casefold()
            if tier == "starter":
                result["starter"].append(applicant)
            elif tier == "experienced":
                result["experienced"].append(applicant)
            else:
                result["warnings"].append(f"row {row_number}: unknown tier {tier}")
    except csv.Error as exc:
        raise ValueError("invalid CSV data") from exc
    return result

